class Label:
    def __init__(self, text):
        self.text = text

    def render(self):
        return self.text

class FramedLabel(Label):
    def render(self):
        return "[" + self.render() + "]"

plain = Label("Map")
framed = FramedLabel("Map")
print(plain.render())
print(framed.render())
